    const results = [];
    const baseIdx = (page - 1) * 10;
    for (let i = 0; i < 10; i++) {
      const idx = baseIdx + i;
      results.push({
        id: idx,
        title: `${category} Article ${idx + 1}`,
        description: `This is a summary for ${category} article number ${idx + 1}.`,
        imageUrl: `https://source.unsplash.com/random/400x200?${category.toLowerCase()}&sig=${idx}`,
        content: `Full content for ${category} article ${idx + 1}.`,
        category,
        comments: []
      });
    }
    return { results };
  }
};
